// benzo auction addresses — fresh shielded addresses of THIS auction's own vault (the view-only wallet
// `auction keys` created at state/vaults/<id>/wallet), generated by the same tool the harness uses
// (benzo-pczt address). They are PUBLIC deposit/escrow addresses
// (R78b class C): deposit slots in the signed manifest, the fee-reserve deposit and the seller destination,
// so printing them is allowed. The harness-side evidence redactor registers each vault address it prints
// This command holds no evidence writer.
import { existsSync } from "node:fs";
import path from "node:path";
import { requireThat } from "../../manifest/schema";

export const noun = "auction", verb = "addresses";
export const help = "benzo auction addresses --id AUCTION_ID --count N — print {auction_id, addresses}: N fresh shielded addresses of this auction's vault (state/vaults/<id>/wallet), one benzo-pczt address call each; refuses if the vault does not exist";

export async function run(argv: string[]): Promise<number | object> {
  const o: Record<string, string> = {};
  for (let i = 0; i < argv.length; i += 2) {
    if (!["--id", "--count"].includes(argv[i]) || argv[i + 1] === undefined) {
      process.stderr.write(`ERROR auction addresses usage: ${help}\n`);
      return 2;
    }
    o[argv[i].slice(2)] = argv[i + 1];
  }
  try {
    // settle/io resolves BNZ_STATE_DIR at import time; import it here so `benzo --help` runs with no state dir.
    const { ROOT, STATE, env, run: execute } = await import("../../settle/io");
    const { pcztBin } = await import("../../manifest/paths");
    requireThat(/^[0-9a-f]{64}$/.test(o.id ?? ""), "auction id");
    const count = Number(o.count);
    requireThat(Number.isInteger(count) && count >= 1 && count <= 64, "count must be an integer in 1..64");
    const wallet = path.join(STATE, "vaults", o.id, "wallet");
    requireThat(existsSync(wallet), `vault ${wallet} does not exist; run benzo auction keys first`);
    const net = env("BNZ_NETWORK");
    const shape = net === "main" ? /^u1[0-9a-z]+$/ : /^utest1[0-9a-z]+$/;
    const addresses: string[] = [];
    for (let i = 0; i < count; i++) {
      const out = execute(pcztBin(ROOT, STATE), ["address", wallet, "--network", net]);
      const ua = out.trim().split("\n").at(-1)!;
      requireThat(shape.test(ua), "benzo-pczt printed no address");
      addresses.push(ua);
    }
    return { auction_id: o.id, addresses };
  } catch (e) {
    process.stderr.write(`ERROR auction addresses ${(e as Error).message}\n`);
    return 1;
  }
}
